// Generated by APIX (apix add agent-wallet --chain near).
// Tools you can hand to a language model. Whatever the model asks for, the
// payment goes through the vault contract, so the owner's limits hold even
// against prompt injection.
import 'server-only';
import { payFromVault, getVaultStatus, formatNear } from './agent-vault';

const payParameters = {
  type: 'object',
  properties: {
    to: { type: 'string', description: 'NEAR account to pay, e.g. shop.testnet. Must be on the vault allowlist.' },
    amount_near: { type: 'string', description: 'Amount in NEAR, e.g. "0.1"' },
    memo: { type: 'string', description: 'Why this payment is made (stored on-chain)' },
  },
  required: ['to', 'amount_near', 'memo'],
  additionalProperties: false,
} as const;

const statusParameters = { type: 'object', properties: {}, additionalProperties: false } as const;

const descriptions = {
  near_pay: 'Pay an allowlisted NEAR account from the agent vault. Payments over the limits are sent to the owner for approval instead.',
  near_vault_status: 'Read the vault limits, what was spent today and what is left.',
};

/** OpenAI Chat Completions / Responses format */
export const openAiTools = [
  { type: 'function' as const, function: { name: 'near_pay', description: descriptions.near_pay, parameters: payParameters } },
  { type: 'function' as const, function: { name: 'near_vault_status', description: descriptions.near_vault_status, parameters: statusParameters } },
];

/** Anthropic Messages format */
export const anthropicTools = [
  { name: 'near_pay', description: descriptions.near_pay, input_schema: payParameters },
  { name: 'near_vault_status', description: descriptions.near_vault_status, input_schema: statusParameters },
];

/** Runs a tool call and returns a short text result for the model */
export async function runVaultTool(name: string, args: Record<string, unknown>): Promise<string> {
  if (name === 'near_vault_status') {
    const s = await getVaultStatus();
    return `Vault ${s.vaultId}: ${s.paused ? 'PAUSED' : 'active'}. Per payment max ${formatNear(s.policy.per_tx_limit)} NEAR, ` +
      `spent today ${formatNear(s.spent_in_window)} of ${formatNear(s.policy.daily_limit)} NEAR. Allowed receivers: ${s.allowlist.join(', ')}.`;
  }
  if (name === 'near_pay') {
    const outcome = await payFromVault({
      to: String(args.to ?? ''),
      amountNear: String(args.amount_near ?? ''),
      memo: typeof args.memo === 'string' ? args.memo.slice(0, 200) : undefined,
      escalate: true,
    });
    if (outcome.status === 'paid') return `Paid. Transaction ${outcome.txHash}.`;
    if (outcome.status === 'pending_approval') return `Not paid yet: ${outcome.reason}. Sent to the owner for approval as request #${outcome.requestId}.`;
    return `Refused by the vault: ${outcome.reason}. Do not retry with a different receiver or split the amount.`;
  }
  return `Unknown tool ${name}.`;
}
